11	        public string Format(IniData iniData, IniFormattingConfiguration format)
12	        {
13	            var sb = new StringBuilder();
14	
15	            // Write global properties
16	            WriteProperties(iniData.Global, sb, iniData.Scheme, format);
17	
18	            //Write sections
19	            foreach (var section in iniData.Sections)
20	            {
21	                //Write current section
22	                WriteSection(section, sb, iniData.Scheme, format);
23	            }
24	
25	            var newLineLength = format.NewLineString.Length;
26	            
27	            // Remove the last new line
28	            sb.Remove(sb.Length - newLineLength, newLineLength);
29	
30	            return sb.ToString();
31	        }
