34	
35	        protected virtual void WriteSection(Section section,
36	                                            StringBuilder sb,
37	                                            IniScheme scheme,
38	                                            IniFormattingConfiguration format)
39	        {
40	            // Comments
41	            WriteComments(section.Comments, sb, scheme, format);
42	
43	            // Write blank line before section, but not if it is the first line
44	            if (format.NewLineBeforeSection && sb.Length > 0)
45	            {
46	                sb.Append(format.NewLineString);
47	            }
48	
49	            // Write section name
50	            sb.Append($"{scheme.SectionStartString}{section.Name}{scheme.SectionEndString}{format.NewLineString}");
51	
52	            if (format.NewLineAfterSection)
53	            {
54	                sb.Append(format.NewLineString);
55	            }
56	
